    result = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        result[i][0] = 1
        for j in range(1, i + 1):
            result[i][j] = (result[i - 1][j - 1] + result[i - 1][j]) % mod
    return result


def matrix_multiply(a, b, mod):
    bt = list(zip(*b))
    result = [[0] * SIZE for _ in range(SIZE)]

    for i in range(SIZE):
        row = a[i]
        result_row = result[i]
        for j in range(SIZE):
            column = bt[j]
            total = 0
            for k in range(SIZE):
                total += row[k] * column[k]
            result_row[j] = total % mod

    return result


